-- Price board : les deux requêtes du Script, sur l'entrepôt WH_Chai (type Requête)
-- Résultat 0 : le marché du jour en une ligne · Résultat 1 : les lignes <tr> du tableau HTML, triées par prix moyen
-- Prix moyen pondéré : valeur totale divisée par le poids vendu ; un lot invendu a un prix NULL
WITH l AS (SELECT origin, garden, grade, CAST(lot_no AS int) AS lot_no, CAST(kg AS int) AS kg, CAST(price_usd_kg AS float) AS p FROM LH_Chai.dbo.auction_lots) SELECT COUNT(*) AS lots, COUNT(p) AS sold, CAST(SUM(CASE WHEN p IS NOT NULL THEN kg END) / 1000.0 AS decimal(9,2)) AS tonnes_sold, CAST(SUM(kg * p) / SUM(CASE WHEN p IS NOT NULL THEN kg END) AS decimal(5,2)) AS avg_usd_kg, CAST(SUM(kg * p) AS decimal(12,1)) AS value_usd, (SELECT TOP 1 CONCAT('lot ', lot_no, ', ', garden, ' (', origin, '), ', grade, ', ', p, ' USD/kg') FROM l ORDER BY p DESC) AS best_lot FROM l;
WITH l AS (SELECT origin, CAST(kg AS int) AS kg, CAST(price_usd_kg AS float) AS p FROM LH_Chai.dbo.auction_lots), t AS (SELECT origin, COUNT(*) AS lots, COUNT(p) AS sold, CAST(SUM(CASE WHEN p IS NOT NULL THEN kg END) / 1000.0 AS decimal(9,2)) AS tonnes, CAST(SUM(kg * p) / SUM(CASE WHEN p IS NOT NULL THEN kg END) AS decimal(5,2)) AS avg_usd_kg, MAX(p) AS top_usd_kg FROM l GROUP BY origin) SELECT STRING_AGG(CONCAT('<tr><td>', origin, '</td><td>', sold, ' / ', lots, '</td><td>', tonnes, '</td><td>', avg_usd_kg, '</td><td>', top_usd_kg, '</td></tr>'), '') WITHIN GROUP (ORDER BY avg_usd_kg DESC) AS html_rows FROM t;
